package com.bookstore.review;
import jakarta.persistence.*; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.time.LocalDateTime; import java.util.*;
@Entity @Table(name="reviews") class Review { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; Long userId; Long bookId; Integer rating; String comment; LocalDateTime createdAt=LocalDateTime.now(); public Long getId(){return id;} public Long getUserId(){return userId;} public Long getBookId(){return bookId;} public Integer getRating(){return rating;} public String getComment(){return comment;} public void setUserId(Long v){userId=v;} public void setBookId(Long v){bookId=v;} public void setRating(Integer v){rating=v;} public void setComment(String v){comment=v;} }
interface ReviewRepository extends JpaRepository<Review,Long>{List<Review> findByBookId(Long bookId);}
record ReviewRequest(@NotNull Long bookId,@NotNull @Min(1) @Max(5) Integer rating,String comment){}
@RestController @RequestMapping("/api/reviews") class ReviewController { private final ReviewRepository reviews; ReviewController(ReviewRepository r){reviews=r;} @GetMapping("/book/{bookId}") List<Review> byBook(@PathVariable Long bookId){return reviews.findByBookId(bookId);} @PostMapping Review create(Authentication a,@Valid @RequestBody ReviewRequest r){var x=new Review();x.setUserId(0L);x.setBookId(r.bookId());x.setRating(r.rating());x.setComment(r.comment());return reviews.save(x);} }
